import sys
from typing import Generator, Any

def generate_ts_component() -> str:
    """
    Generates a production-ready TypeScript React component 
    for a Login Button with loading state and type-safe onClick handling.
    """
    typescript_code: str = """import React from 'react';

/**
 * Interface defining the props for the LoginButton component.
 */
export interface LoginButtonProps {
  /** Current loading state of the login action */
  isLoading: boolean;
  /** Click handler function, supporting both synchronous and asynchronous actions */
  onClick: (event: React.MouseEvent<HTMLButtonElement>) => void | Promise<void>;
  /** Optional custom CSS classes for styling flexibility */
  className?: string;
  /** Optional disabled state, defaults to false */
  disabled?: boolean;
  /** Custom inner content of the button, defaults to 'Sign In' */
  children?: React.ReactNode;
}

/**
 * LoginButton Component
 * 
 * Features:
 * - Proper TS Typing for React Mouse Events.
 * - Accessibility (a11y) support using aria-busy and aria-disabled.
 * - Robust handling of concurrent clicks during loading state.
 * - Flexible styling support via className prop.
 */
export const LoginButton: React.FC<LoginButtonProps> = ({
  isLoading,
  onClick,
  className = '',
  disabled = false,
  children = 'Sign In',
}) => {
  // Disable button if explicitly disabled or currently loading
  const isButtonDisabled: boolean = disabled || isLoading;

  const handleClick = async (event: React.MouseEvent<HTMLButtonElement>): Promise<void> => {
    // Prevent execution if button is in a disabled/loading state
    if (isButtonDisabled) {
      event.preventDefault();
      return;
    }

    try {
      await onClick(event);
    } catch (error) {
      console.error('Login action failed:', error);
    }
  };

  return (
    <button
      type="submit" // Recommended 'submit' for form accessibility, can be changed to 'button'
      onClick={handleClick}
      disabled={isButtonDisabled}
      aria-busy={isLoading}
      aria-disabled={isButtonDisabled}
      className={`login-button ${isLoading ? 'is-loading' : ''} ${className}`.trim()}
    >
      {isLoading ? (
        <span className="spinner-container" aria-live="polite">
          <svg 
            className="animate-spin spinner" 
            viewBox="0 0 24 24" 
            fill="none" 
            xmlns="http://www.w3.org/2000/svg"
            width="1em"
            height="1em"
          >
            <circle 
              className="opacity-25" 
              cx="12" 
              cy="12" 
              r="10" 
              stroke="currentColor" 
              strokeWidth="4"
            />
            <path 
              className="opacity-75" 
              fill="currentColor" 
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            />
          </svg>
          <span className="sr-only">Loading...</span>
        </span>
      ) : (
        <span className="button-content">{children}</span>
      )}
    </button>
  );
};

export default LoginButton;
"""
